    res.setHeader('content-type', 'text/plain; charset=utf-8');
    return res.end('éé');
  }
  req.resume();
  req.on('end', () => res.end('ok'));
});
server.listen(0, '127.0.0.1', async () => {
  const base = `http://127.0.0.1:${server.address().port}`;
  try {
    const exact = request.post(base).maxRequestSize(2).send('é');
    await exact;
    assert.strictEqual(exact.hasSizeError(), false);

    hits = 0;
    const oversized = request.post(base).maxRequestSize(1).retry(2).send('é');
    await assert.rejects(oversized, error => error.code === 'ETOOLARGE');
